def transform(g):
    from collections import Counter
    cnt=Counter(v for row in g for v in row)
    bg=max(cnt,key=cnt.get); mk=min(cnt,key=cnt.get)
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(1,w-1):
            if g[r][c]==bg and g[r][c-1]==mk and g[r][c+1]==mk:
                out[r][c]=2
    return out
